def shear_left_bottom(grid):
    rb = max(r for r,row in enumerate(grid) if any(row))
    out=[[0]*len(grid[0]) for _ in grid]
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v:
                nc = c - (rb - r)
                if 0 <= nc < len(grid[0]):
                    out[r][nc]=v
    return out

